		vimInsertModeRemaps: () => Z(h(), ge()).optional().catch(void 0).describe("Vim INSERT-mode key-sequence remaps, e.g. {\"jj\": \"<Esc>\"}. Each key is exactly two printable characters typed in sequence; \"<Esc>\" (return to NORMAL mode) is the only supported target. Applies when editorMode is \"vim\"."),
		verbose: () => x().optional().describe("Show full tool output instead of truncated summaries"),
		preferredNotifChannel: () => B(c2).optional().catch(void 0).describe("Preferred OS notification channel"),
		autoCompactEnabled: () => x().optional().describe("Automatically compact conversation when context fills"),
